1	// path: src/apps/vinyl-angel/store/useVinylStore.ts
2	
3	import { create } from 'zustand';
4	import { persist } from 'zustand/middleware';
5	import type { VinylLocalTheme, VinylPlayerSettings, VinylSessionStats, ShopItem, PlaylistItem, Tier2EventEntry, CustomPlaylist, ChannelOriginItem, ChannelStatus } from '../types';
6	import { useInventoryStore } from '../../../store/useInventoryStore';
7	
8	export const SHOP_CATALOG: ShopItem[] = [
9	  {
10	    id: 'angel-roll-ticket',
11	    name: 'Angel Roll Ticket 🎟️',
12	    description: 'Dimensional summoning ticket forged from 25 Celestial Discs. Used in the Grand Dimensional Nexus (Modern Day world) where valuable objects of all dimensions converge.',
13	    category: 'ticket',
14	    priceDiscs: 25,
15	    rewardTicket: 'angel-roll',
16	    isLocked: false,
17	    iconName: 'Ticket',
18	    color: '#ffd86b',
19	    perkEffect: 'Summons celestial artifacts & relics in Modern Day.',
20	    consumable: true,
21	  },
22	  {
23	    id: 'solar-flora-ticket',
24	    name: 'Solar Flora Ticket 🌻',
25	    description: 'Extracted from the high-yield solar crops of Farm Beta. Awaiting Modern Day convergence.',
26	    category: 'ticket',
27	    priceDiscs: 50,
28	    isLocked: true,
29	    lockReason: 'Dimension Locked: Farm Alpha/Beta Nexus',
30	    iconName: 'Sparkles',
31	    color: '#fbbf24',
32	    perkEffect: 'Flora bio-essence synthesizer.',
33	  },
34	  {
35	    id: 'codex-relic-ticket',
36	    name: 'Codex Relic Ticket 📖',
37	    description: 'Ancient cipher tablet from the Artifact Codex archive. Sealed until dimensional breach.',
38	    category: 'ticket',
39	    priceDiscs: 50,
40	    isLocked: true,
41	    lockReason: 'Dimension Locked: Artifact Codex Matrix',
42	    iconName: 'Shield',
43	    color: '#a78bfa',
44	    perkEffect: 'Decodes lost hazard protocols.',
45	  },
46	  {
47	    id: 'golden-stylus',
48	    name: 'Golden Stylus 🪽',
49	    description: 'A handcrafted needle forged in celestial gold. Bestows gilded glow across the player interface.',
50	    category: 'cosmetic',
51	    priceDiscs: 100,
52	    isLocked: true,
53	    lockReason: 'Modern Day Nexus Crafting Required',
54	    iconName: 'Sparkles',
55	    color: '#ffd86b',
56	    perkEffect: 'Gilded player borders and audio visual sparkle effects.',
57	  },
58	  {
59	    id: 'abyssal-needle',
60	    name: 'Abyssal Needle ✦',
61	    description: 'A needle crafted from collapsed dark matter. Unlocks cosmic event horizon pulses.',
62	    category: 'cosmetic',
63	    priceDiscs: 150,
64	    isLocked: true,
65	    lockReason: 'Modern Day Nexus Crafting Required',
66	    iconName: 'Moon',
67	    color: '#a78bfa',
68	    perkEffect: 'Deep void pulses on each track transition.',
69	  },
70	  {
71	    id: 'time-multiplier-2x',
72	    name: 'Harmonic Catalyst (Boost)',
73	    description: 'Doubles the resonance generated for rated songs.',
74	    category: 'booster',
75	    priceDiscs: 60,
76	    isLocked: true,
77	    lockReason: 'Modern Day Nexus Crafting Required',
78	    iconName: 'Zap',
79	    color: '#38bdf8',
80	    perkEffect: 'Multiplies harmonic disc output.',
81	    consumable: true,
82	  },
83	];
84	
85	interface VinylStoreState {
86	  // Currencies
87	  discs: number;
88	  angelRollTickets: number;
89	
90	  // Theming & Cosmetics
91	  localTheme: VinylLocalTheme;
92	  unlockedThemes: VinylLocalTheme[];
93	  purchasedItemIds: string[];
94	  equippedStylus: string | null;
95	  boosterCharges: number;
96	
97	  // Settings & Session Stats
98	  settings: VinylPlayerSettings;
99	  stats: VinylSessionStats;
100	
101	  // Inter-tab Transfer State
102	  queuedTrackForGameplay: PlaylistItem | null;
103	  queuedPlaylistForGameplay: string | null;
104	
105	  // Resilient Offline Event Outbox
106	  offlineOutbox: Tier2EventEntry[];
107	
108	  // Sovereign Custom Playlists (Channel Federations)
109	  customPlaylists: CustomPlaylist[];
110	
111	  // Shared Channel & Metadata State (synchronized across all tabs)
112	  channelList: ChannelOriginItem[];
113	  channelMetaMap: Record<string, { status: ChannelStatus; notes?: string }>;
114	
115	  // Blocked Songs State (immediate pool exclusion)
116	  blockedSongIds: string[];
117	
118	  // Actions
119	  earnDiscs: (count: number) => void;
120	  spendDiscs: (count: number) => boolean;
121	  addAngelTickets: (count: number) => void;
122	  spendAngelTickets: (count: number) => boolean;
123	
124	  setLocalTheme: (theme: VinylLocalTheme) => void;
125	  unlockTheme: (theme: VinylLocalTheme) => void;
126	  buyShopItem: (item: ShopItem) => boolean;
127	  equipStylus: (stylusId: string | null) => void;
128	  consumeBoosterCharge: () => boolean;
129	  addBoosterCharges: (charges: number) => void;
130	  updateSettings: (partial: Partial<VinylPlayerSettings>) => void;
131	  incrementRatingStats: (discsEarned?: number) => void;
132	  recordSyncCompleted: () => void;
133	  hasItem: (itemId: string) => boolean;
134	  setQueuedTrackForGameplay: (track: PlaylistItem | null) => void;
135	  setQueuedPlaylistForGameplay: (source: string | null) => void;
136	  enqueueOfflineEvent: (evt: Tier2EventEntry) => void;
137	  clearOfflineOutbox: () => void;
138	  removeOfflineEvents: (timestamps: string[]) => void;
139	
140	  setCustomPlaylists: (playlists: CustomPlaylist[]) => void;
141	  addCustomPlaylist: (playlist: CustomPlaylist) => void;
142	  updateCustomPlaylist: (playlist: CustomPlaylist) => void;
143	  removeCustomPlaylist: (playlistId: string) => void;
144	
145	  setChannelList: (channels: ChannelOriginItem[]) => void;
146	  setChannelMetaMap: (metaMap: Record<string, { status: ChannelStatus; notes?: string }>) => void;
147	  updateChannelStatus: (channelId: string, channelName: string, status: ChannelStatus) => void;
148	
149	  addBlockedSong: (songId: string) => void;
150	  isBlocked: (songId: string) => boolean;
151	  clearBlockedSongs: () => void;
152	}
153	
154	export const useVinylStore = create<VinylStoreState>()(
155	  persist(
156	    (set, get) => ({
157	      discs: 0,
158	      angelRollTickets: 0,
159	      localTheme: 'celestial-gold',
160	      unlockedThemes: ['celestial-gold', 'obsidian-abyss'],
161	      purchasedItemIds: [],
162	      equippedStylus: 'golden-stylus',
163	      boosterCharges: 0,
164	      settings: {
165	        autoplay: true,
166	        defaultPassScore: '5+',
167	        soundEffects: true,
168	        autoSync: false,
169	      },
170	      stats: {
171	        sessionRatingsCount: 0,
172	        totalDiscsEarned: 0,
173	        lastSyncTimestamp: null,
174	      },
175	      queuedTrackForGameplay: null,
176	      offlineOutbox: [],
177	
178	      earnDiscs: (count: number) => {
179	        const amount = Math.max(0, count);
180	        set((s) => ({ discs: s.discs + amount }));
181	        // Sync to universal inventory
182	        useInventoryStore.getState().addDiscs(amount);
183	      },
184	
185	      spendDiscs: (count: number) => {
186	        if (get().discs < count) return false;
187	        set((s) => ({ discs: s.discs - count }));
188	        useInventoryStore.getState().spendDiscs(count);
189	        return true;
190	      },
191	
192	      addAngelTickets: (count: number) => {
193	        const amount = Math.max(0, count);
194	        set((s) => ({ angelRollTickets: s.angelRollTickets + amount }));
195	        useInventoryStore.getState().addAngelTickets(amount);
196	      },
197	
198	      spendAngelTickets: (count: number) => {
199	        if (get().angelRollTickets < count) return false;
200	        set((s) => ({ angelRollTickets: s.angelRollTickets - count }));
201	        useInventoryStore.getState().spendAngelTickets(count);
202	        return true;
203	      },
204	
205	      setLocalTheme: (theme) => {
206	        if (get().unlockedThemes.includes(theme)) {
207	          set({ localTheme: theme });
208	        }
209	      },
210	
211	      unlockTheme: (theme) => {
212	        if (!get().unlockedThemes.includes(theme)) {
213	          set((s) => ({ unlockedThemes: [...s.unlockedThemes, theme] }));
214	        }
215	      },
216	
217	      buyShopItem: (item) => {
218	        if (item.isLocked) return false;
219	
220	        const price = item.priceDiscs ?? 25;
221	        if (get().discs < price) return false;
222	
223	        // Deduct Discs
224	        get().spendDiscs(price);
225	
226	        if (item.id === 'angel-roll-ticket') {
227	          get().addAngelTickets(1);
228	          set((s) => ({
229	            purchasedItemIds: [...s.purchasedItemIds, item.id],
230	          }));
231	          return true;
232	        }
233	
234	        return false;
235	      },
236	
237	      equipStylus: (stylusId) => set({ equippedStylus: stylusId }),
238	
239	      consumeBoosterCharge: () => {
240	        const current = get().boosterCharges;
241	        if (current > 0) {
242	          set({ boosterCharges: current - 1 });
243	          return true;
244	        }
245	        return false;
246	      },
247	
248	      addBoosterCharges: (charges) =>
249	        set((s) => ({ boosterCharges: s.boosterCharges + charges })),
250	
251	      updateSettings: (partial) =>
252	        set((s) => ({ settings: { ...s.settings, ...partial } })),
253	
254	      incrementRatingStats: (discsEarned = 3) =>
255	        set((s) => ({
256	          stats: {
257	            ...s.stats,
258	            sessionRatingsCount: s.stats.sessionRatingsCount + 1,
259	            totalDiscsEarned: s.stats.totalDiscsEarned + discsEarned,
260	          },
261	        })),
262	
263	      recordSyncCompleted: () =>
264	        set((s) => ({
265	          stats: {
266	            ...s.stats,
267	            lastSyncTimestamp: new Date().toLocaleTimeString(),
268	          },
269	        })),
270	
271	      hasItem: (itemId) => get().purchasedItemIds.includes(itemId),
272	
273	      setQueuedTrackForGameplay: (track) => set({ queuedTrackForGameplay: track }),
274	      queuedPlaylistForGameplay: null,
275	      setQueuedPlaylistForGameplay: (source) => set({ queuedPlaylistForGameplay: source }),
276	
277	      customPlaylists: [],
278	      channelList: [],
279	      channelMetaMap: {},
280	
281	      setCustomPlaylists: (playlists) => set({ customPlaylists: playlists }),
282	      addCustomPlaylist: (playlist) =>
283	        set((s) => ({
284	          customPlaylists: [playlist, ...s.customPlaylists.filter((p) => p.id !== playlist.id)],
285	        })),
286	      updateCustomPlaylist: (playlist) =>
