180	      else if (/arc\s*0?1|morning/i.test(b)) chRecord.timeblock_arc1++;
181	      else if (/arc\s*0?2|battle/i.test(b)) chRecord.timeblock_arc2++;
182	      else if (/arc\s*0?3|night/i.test(b)) chRecord.timeblock_arc3++;
