201	        score_6_count: JSON.stringify(chRecord.score_6_count),
202	        score_7_count: JSON.stringify(chRecord.score_7_count),
203	        timeblock_arc0: chRecord.timeblock_arc0,
204	        timeblock_arc1: chRecord.timeblock_arc1,
205	        timeblock_arc2: chRecord.timeblock_arc2,
206	        timeblock_arc3: chRecord.timeblock_arc3,
207	        timeblock_arc4: chRecord.timeblock_arc4,
208	        unlock_date: chRecord.unlock_date,
209	        updated_at: chRecord.updated_at,
210	      },
211	    },
212	  });
213	
214	  // 2. Also record to Tier 2 JSONL event buffer
215	  await executeOrder({
216	    project_id: projectId,
