485	    const act = (evt.action || '').toLowerCase().trim();
486	    if (act === 'block') continue;
487	
488	    // Check if event is targeted to an entire channel
489	    if (evt.target_type === 'channel' || (evt.channel_id && evt.channel_id === evt.id)) {
490	      const chId = evt.channel_id || evt.id;
