666	export async function syncTier3ToTier4(projectId: string) {
667	  const [t3Records, channelRecords] = await Promise.all([
668	    fetchTier3State(projectId),
669	    fetchChannelState(projectId),
670	  ]);
671	
672	  const t4ValidBatchMap: Record<string, Record<string, unknown>> = {};
673	
674	  // Index individual track ratings
675	  const trackMap: Record<string, Tier3StateRecord> = {};
676	  for (const t3 of t3Records) {
677	    trackMap[t3.id] = t3;
678	  }
679	
680	  // Fetch track lists for rated channels to apply channel-wide metadata
681	  const activeChannelIds = Object.keys(channelRecords);
682	  const channelTracksMap: Record<string, string[]> = {};
683	
684	  if (activeChannelIds.length > 0) {
685	    try {
686	      const chTracksRes = await executeOrder<Record<string, string[]>>({
687	        project_id: projectId,
688	        tier: '1',
689	        order: {
690	          action: 'get_channel_tracks',
691	          data: { channel_ids: activeChannelIds },
692	        },
693	      });
694	      if (chTracksRes.data) {
695	        Object.assign(channelTracksMap, chTracksRes.data);
696	      }
697	    } catch (e) {
698	      console.warn('[syncTier3ToTier4] Error fetching channel tracks:', e);
699	    }
700	  }
701	
702	  const processedSongIds = new Set<string>();
703	
704	  // Process all songs belonging to rated channels (channel metadata applies to every song of that channel)
705	  for (const chId of activeChannelIds) {
706	    const ch = channelRecords[chId];
707	    const songsInChannel = channelTracksMap[chId] || [];
708	
709	    for (const songId of songsInChannel) {
710	      processedSongIds.add(songId);
711	
712	      const individualT3 = trackMap[songId];
713	      let compositeRecord: Tier3StateRecord;
714	
715	      if (individualT3) {
716	        compositeRecord = {
717	          id: songId,
718	          score_3_count: [...ch.score_3_count, ...individualT3.score_3_count],
719	          score_4_count: [...ch.score_4_count, ...individualT3.score_4_count],
720	          score_5_count: [...ch.score_5_count, ...individualT3.score_5_count],
721	          score_6_count: [...ch.score_6_count, ...individualT3.score_6_count],
722	          score_7_count: [...ch.score_7_count, ...individualT3.score_7_count],
723	          timeblock_arc0: ch.timeblock_arc0 + individualT3.timeblock_arc0,
724	          timeblock_arc1: ch.timeblock_arc1 + individualT3.timeblock_arc1,
725	          timeblock_arc2: ch.timeblock_arc2 + individualT3.timeblock_arc2,
726	          timeblock_arc3: ch.timeblock_arc3 + individualT3.timeblock_arc3,
727	          timeblock_arc4: ch.timeblock_arc4 + individualT3.timeblock_arc4,
728	          unlock_date: individualT3.unlock_date || ch.unlock_date,
729	          hazard_rank: individualT3.hazard_rank ?? null,
730	        };
731	      } else {
732	        compositeRecord = {
733	          id: songId,
734	          score_3_count: [...ch.score_3_count],
735	          score_4_count: [...ch.score_4_count],
736	          score_5_count: [...ch.score_5_count],
737	          score_6_count: [...ch.score_6_count],
738	          score_7_count: [...ch.score_7_count],
739	          timeblock_arc0: ch.timeblock_arc0,
740	          timeblock_arc1: ch.timeblock_arc1,
741	          timeblock_arc2: ch.timeblock_arc2,
742	          timeblock_arc3: ch.timeblock_arc3,
743	          timeblock_arc4: ch.timeblock_arc4,
744	          unlock_date: ch.unlock_date,
745	          hazard_rank: null,
746	        };
747	      }
748	
749	      if (compositeRecord.hazard_rank) {
750	        const hazard = calculateHazardLevel(compositeRecord);
751	        t4ValidBatchMap[songId] = {
752	          id: songId,
753	          hazard_level: hazard,
754	          played: calculateTotalPlayed(compositeRecord),
755	          timeblock: getDominantTimeblock(compositeRecord),
756	          unlock_date: compositeRecord.unlock_date,
757	        };
758	      }
759	    }
760	  }
761	
762	  // Process remaining individual track ratings whose channels weren't batch rated
763	  for (const t3 of t3Records) {
764	    if (processedSongIds.has(t3.id)) continue;
765	
766	    if (t3.hazard_rank) {
767	      const hazard = calculateHazardLevel(t3);
768	      t4ValidBatchMap[t3.id] = {
769	        id: t3.id,
770	        hazard_level: hazard,
771	        played: calculateTotalPlayed(t3),
772	        timeblock: getDominantTimeblock(t3),
773	        unlock_date: t3.unlock_date,
774	      };
775	    }
776	  }
777	
778	  if (Object.keys(t4ValidBatchMap).length > 0) {
779	    await executeOrder({
780	      project_id: projectId,
781	      tier: '4',
782	      order: {
783	        action: 'batch_upsert',
784	        data: t4ValidBatchMap,
785	      },
786	    });
787	  }
788	
789	  invalidateVinylCache(projectId);
790	  return {
791	    syncedCount: Object.keys(t4ValidBatchMap).length,
792	    purgedCount: 0,
793	    badKpiIds: [],
794	  };
795	}
