1286	export async function streamPlaylistIngestion(
1287	  options: {
1288	    urls?: string[];
1289	    max_playlists?: number;
1290	    max_per_playlist?: number;
1291	  },
1292	  onEvent: (event: CurlerStreamEvent) => void,
1293	  signal?: AbortSignal
1294	): Promise<void> {
1295	  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
1296	    method: 'POST',
1297	    headers: { 'Content-Type': 'application/json' },
1298	    body: JSON.stringify(options),
1299	    signal,
1300	  });
1301	
1302	  if (!res.ok) {
1303	    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
1304	  }
1305	
1306	  if (!res.body) {
1307	    throw new Error('ReadableStream not supported on response body.');
1308	  }
1309	
1310	  const reader = res.body.getReader();
1311	  const decoder = new TextDecoder('utf-8');
1312	  let buffer = '';
1313	
1314	  while (true) {
1315	    const { done, value } = await reader.read();
1316	    if (done) break;
1317	
1318	    buffer += decoder.decode(value, { stream: true });
1319	    const chunks = buffer.split('\n\n');
1320	    buffer = chunks.pop() || '';
1321	
1322	    for (const chunk of chunks) {
1323	      const trimmed = chunk.trim();
1324	      if (trimmed.startsWith('data:')) {
1325	        try {
1326	          const jsonStr = trimmed.slice(5).trim();
1327	          if (jsonStr) {
1328	            const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1329	            onEvent(eventData);
1330	          }
1331	        } catch (err) {
1332	          console.warn('[Curler Stream] Failed to parse SSE chunk:', err);
1333	        }
1334	      }
1335	    }
1336	  }
1337	
1338	  if (buffer.trim().startsWith('data:')) {
1339	    try {
1340	      const jsonStr = buffer.trim().slice(5).trim();
1341	      if (jsonStr) {
1342	        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1343	        onEvent(eventData);
1344	      }
1345	    } catch (_) {}
1346	  }
1347	
1348	  // Clear static caches after streaming completes
1349	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
1350	  invalidateVinylCache();
1351	}
