// path: src/apps/vinyl-angel/components/VinylGallery.tsx

// =============================================================================
// [VINYL ANGEL GALLERY & LEADERBOARD COMPONENT WITH INTEGRATED ETL PIPELINE]
// =============================================================================
import { useState, useEffect, useMemo, type MouseEvent, type FC } from 'react';
import { executeOrder } from '../../../services/api';
import {
  fetchEligibleTier4List,
  resolvePageMetadataOnDemand,
  syncTier2ToTier3,
  syncTier3ToTier4,
  searchFullCatalog,
} from '../services/engine';
import { useVinylStore } from '../store/useVinylStore';
import { formatDuration } from '../../../utils/time';
import { GLOBAL_RANKS } from '../../../utils/rank';
import { HazardBadge } from '../../../components/HazardBadge';
import { Pagination } from '../../../components/Pagination';
import type { VinylDisplayCard, Tier2EventEntry } from '../types';
import {
  Search,
  SlidersHorizontal,
  ArrowDown10,
  ArrowUp01,
  ArrowUpDown,
  Compass,
  Crown,
  Copy,
  Check,
  X,
  RefreshCw,
  Sparkles,
  Database,
  CheckCircle2,
  AlertCircle,
  Zap,
  DownloadCloud,
  Radio,
  ArrowRight,
  Disc3,
  Play,
} from 'lucide-react';

const PAGE_SIZE = 16;

interface VinylGalleryProps {
  projectId?: string;
  onNavigateToIngestion?: () => void;
  onNavigateToGameplay?: () => void;
}

export const VinylGallery: FC<VinylGalleryProps> = ({
  projectId = 'music_app',
  onNavigateToIngestion,
  onNavigateToGameplay,
}) => {
  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;
  const recordSyncCompleted = useVinylStore((s) => s.recordSyncCompleted);
  const lastSyncTimestamp = useVinylStore((s) => s.stats.lastSyncTimestamp);

  const [allEligibleItems, setAllEligibleItems] = useState<VinylDisplayCard[]>([]);
  const [currentPageItems, setCurrentPageItems] = useState<VinylDisplayCard[]>([]);
  const [loading, setLoading] = useState(true);

  // ETL Sync state
  const [pendingEventsCount, setPendingEventsCount] = useState<number>(0);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' } | null>(
    null
  );

  // Filters & Sorting
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedRank, setSelectedRank] = useState('ALL');
  const [hazardSort, setHazardSort] = useState<'desc' | 'asc' | 'none'>('desc');

  // Full Catalog Search State
  const [catalogSearchResults, setCatalogSearchResults] = useState<VinylDisplayCard[] | null>(null);
  const [isCatalogSearching, setIsCatalogSearching] = useState(false);
  const catalogSearchTimerRef = { current: null as ReturnType<typeof setTimeout> | null };

  // Pagination State
  const [currentPage, setCurrentPage] = useState<number>(1);

  // Inspection Modal & Clipboard
  const [inspectItem, setInspectItem] = useState<VinylDisplayCard | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const handlePlayTrackInGameplay = (track: VinylDisplayCard) => {
    useVinylStore.getState().setQueuedTrackForGameplay({
      id: track.id,
      title: track.title,
      channel: track.channel,
      duration: track.duration,
      hazard_level: track.hazard_level,
      played: track.played,
      timeblock: track.timeblock,
    });
    if (onNavigateToGameplay) {
      onNavigateToGameplay();
    }
  };

  const checkPendingLogs = async () => {
    try {
      const res = await executeOrder<Tier2EventEntry[]>({
        project_id: targetProjectId,
        tier: '2',
        order: { action: 'read_all' },
      });
      const list = Array.isArray(res.data) ? res.data : [];
      setPendingEventsCount(list.length);
    } catch {
      setPendingEventsCount(0);
    }
  };

  const loadIndexList = async (forceRefresh = false) => {
    setLoading(true);
    try {
      const data = await fetchEligibleTier4List(targetProjectId, forceRefresh);
      setAllEligibleItems(data);
      await checkPendingLogs();
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadIndexList(false);
  }, [targetProjectId]);

  // Debounced Full Catalog Search (fires after 400ms of idle typing, min 2 chars)
  const handleSearchQueryChange = (query: string) => {
    setSearchQuery(query);
    setCurrentPage(1);

    if (catalogSearchTimerRef.current) {
      clearTimeout(catalogSearchTimerRef.current);
    }

    if (query.trim().length < 2) {
      setCatalogSearchResults(null);
      setIsCatalogSearching(false);
      return;
    }

    setIsCatalogSearching(true);
    catalogSearchTimerRef.current = setTimeout(async () => {
      try {
        const results = await searchFullCatalog(targetProjectId, query.trim(), 50);
        setCatalogSearchResults(results);
      } catch (err) {
        console.warn('[Gallery] Full catalog search failed:', err);
        setCatalogSearchResults(null);
      } finally {
        setIsCatalogSearching(false);
      }
    }, 400);
  };

  const handleFullSync = async () => {
    setIsSyncing(true);
    const startTime = performance.now();
    try {
      // Step 1: Ingest Tier 2 events into Tier 3 matrices & Clear Tier 2 buffer
      const t2Res = await syncTier2ToTier3(targetProjectId);

      // Step 2: Project Tier 3 state into Tier 4 Hazard scores & Purge bad KPI
      const t3Res = await syncTier3ToTier4(targetProjectId);

      const durationMs = Math.round(performance.now() - startTime);

      let msg = `✨ Sync Complete (${durationMs}ms): ${t2Res.eventsProcessed} logs ingested & buffer emptied ➔ ${t3Res.syncedCount} tracks projected to Tier 4!`;
      if (t2Res.blockedCount > 0) {
        msg += ` (🚫 ${t2Res.blockedCount} blacklisted)`;
      }

      showToast(msg, 'success');
      recordSyncCompleted();
      await loadIndexList(true);
    } catch (err: any) {
      showToast(`❌ ETL Sync Error: ${err.message}`, 'error');
    } finally {
      setIsSyncing(false);
    }
  };

  const filteredItems = useMemo(() => {
    // When a catalog search is active, use those results directly
    if (catalogSearchResults !== null && searchQuery.trim().length >= 2) {
      const res = catalogSearchResults.filter((item) => {
        const matchRank = selectedRank === 'ALL' || item.rankCategory === selectedRank;
        return matchRank;
      });
      if (hazardSort === 'desc') return [...res].sort((a, b) => b.hazard_level - a.hazard_level);
      if (hazardSort === 'asc') return [...res].sort((a, b) => a.hazard_level - b.hazard_level);
      return res;
    }

    // Otherwise filter the Tier 4 eligible list locally
    const res = allEligibleItems.filter((item) => {
      const matchQuery =
        item.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (item.timeblock && item.timeblock.toLowerCase().includes(searchQuery.toLowerCase()));
      const matchRank = selectedRank === 'ALL' || item.rankCategory === selectedRank;
      return matchQuery && matchRank;
    });

    if (hazardSort === 'desc') return [...res].sort((a, b) => b.hazard_level - a.hazard_level);
    if (hazardSort === 'asc') return [...res].sort((a, b) => a.hazard_level - b.hazard_level);
    return res;
  }, [allEligibleItems, catalogSearchResults, searchQuery, selectedRank, hazardSort]);

  const totalPages = Math.ceil(filteredItems.length / PAGE_SIZE) || 1;

  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, selectedRank, hazardSort]);

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [totalPages, currentPage]);

  useEffect(() => {
    let isCancelled = false;

    const resolveCurrentPageTracks = async () => {
      if (filteredItems.length === 0) {
        setCurrentPageItems([]);
        return;
      }

      const startIndex = (currentPage - 1) * PAGE_SIZE;
      const targetSlice = filteredItems.slice(startIndex, startIndex + PAGE_SIZE);

      // Render placeholder first so cards appear instantly
      setCurrentPageItems(targetSlice);

      // Catalog search results already have metadata; only Tier 4 items need lazy resolve
      const isCatalogMode = catalogSearchResults !== null && searchQuery.trim().length >= 2;
      if (!isCatalogMode) {
        try {
          const enrichedTracks = await resolvePageMetadataOnDemand(targetProjectId, targetSlice);
          if (!isCancelled) {
            setCurrentPageItems(enrichedTracks);
          }
        } catch (e) {
          console.error('Error loading metadata for page:', e);
        }
      }
    };

    resolveCurrentPageTracks();

    return () => {
      isCancelled = true;
    };
  }, [filteredItems, currentPage, targetProjectId]);

  const toggleSort = () => {
    setHazardSort((prev) => (prev === 'desc' ? 'asc' : prev === 'asc' ? 'none' : 'desc'));
  };

  const copyId = (id: string, e: MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(id);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  return (
    <div className="space-y-6">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-xl bg-[#171320] border border-[#d4af37] text-xs font-semibold shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-bottom-2 text-[#ffd86b] max-w-lg">
          {toast.type === 'success' && (
            <CheckCircle2 className="w-4 h-4 text-emerald-400 flex-shrink-0" />
          )}
          {toast.type === 'error' && (
            <AlertCircle className="w-4 h-4 text-rose-400 flex-shrink-0" />
          )}
          {toast.type === 'info' && <Sparkles className="w-4 h-4 text-[#ffd86b] flex-shrink-0" />}
          <span>{toast.message}</span>
        </div>
      )}

      {/* Dual Operations Control Deck (YouTube Ingestion Link & ETL State Sync) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
        {/* Module 1: Ingestion Pipeline Banner */}
        <div className="lg:col-span-6 p-5 rounded-2xl bg-[#120f18] border border-[#2b2238] shadow-lg flex flex-col justify-between space-y-4">
          <div className="flex items-start gap-3.5">
            <div className="p-2.5 rounded-xl bg-gradient-to-br from-[#291e07] to-[#120f18] border border-[#524124] text-[#ffd86b]">
              <DownloadCloud className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-cinzel text-sm font-bold text-[#ffd86b]">
                  Song Ingestion & Ingestion Lab
                </h3>
              </div>
              <p className="text-xs text-[#8c7a9e] mt-1 leading-relaxed">
                Scan configured YouTube playlists, stream real-time logs, and ingest new songs directly into{' '}
                <code className="text-[#ffd86b] font-mono">system/_1_static.db</code>.
              </p>
            </div>
          </div>

          <div className="pt-2 border-t border-[#1e1728]">
            {onNavigateToIngestion ? (
              <button
                type="button"
                onClick={onNavigateToIngestion}
                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-xs font-cinzel font-bold bg-gradient-to-r from-[#d4af37] to-[#b38b19] text-black hover:brightness-110 shadow-gold-sm transition active:scale-95"
              >
                <DownloadCloud className="w-4 h-4" />
                <span>Curl More Songs Added to Playlists</span>
                <ArrowRight className="w-4 h-4" />
              </button>
            ) : null}
          </div>
        </div>

        {/* Module 2: ETL State Pipeline Sync */}
        <div className="lg:col-span-6 p-5 rounded-2xl bg-[#120f18] border border-[#2b2238] shadow-lg flex flex-col justify-between space-y-4">
          <div className="flex items-start gap-3.5">
            <div className="p-2.5 rounded-xl bg-[#1a1424] border border-[#3d304f] text-[#ffd86b]">
              <Database className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-cinzel text-sm font-bold text-[#ffd86b]">ETL State Pipeline</h3>
                <span className="text-[11px] font-mono px-2 py-0.5 rounded bg-[#171320] text-[#8c7a9e] border border-[#261d33]">
                  {allEligibleItems.length} Ranked Tracks
                </span>
              </div>
              <p className="text-xs text-[#8c7a9e] mt-1">
                {pendingEventsCount > 0 ? (
                  <span className="text-amber-400 font-semibold">
                    ⚡ {pendingEventsCount} pending rating logs in Tier 2 buffer ready to sync.
                  </span>
                ) : (
                  <span>All rating events are processed into Tier 3 & Tier 4 matrix.</span>
                )}
                {lastSyncTimestamp && ` (Last sync: ${lastSyncTimestamp})`}
              </p>
            </div>
          </div>

          <div className="pt-2 border-t border-[#1e1728]">
            <button
              type="button"
              onClick={handleFullSync}
              disabled={isSyncing}
              className={`w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-xs font-cinzel font-bold transition shadow-md active:scale-95 disabled:opacity-50 ${
                pendingEventsCount > 0
                  ? 'bg-gradient-to-r from-[#d4af37] to-[#aa8214] text-black shadow-gold-sm hover:brightness-110 border border-[#ffd86b]'
                  : 'bg-[#1a1424] hover:bg-[#251d33] border border-[#3d304f] text-[#cbd5e1]'
              }`}
            >
              {isSyncing ? (
                <>
                  <RefreshCw className="w-3.5 h-3.5 animate-spin" /> Processing ETL Pipeline...
                </>
              ) : (
                <>
                  <Zap className="w-3.5 h-3.5" /> Sync Logs ➔ Update & Empty Buffer ({pendingEventsCount})
                </>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Search, Filter & Sort Bar */}
      <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-4 p-4 rounded-xl bg-[#100d16] border border-[#261d33] shadow-lg">
        <div className="relative flex-1 flex items-center gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8c7a9e]" />
            <input
              type="text"
              placeholder="Search any song (title, channel, ID) — searches entire 173k+ catalog..."
              value={searchQuery}
              onChange={(e) => handleSearchQueryChange(e.target.value)}
              className="w-full bg-[#171320] border border-[#332842] focus:border-[#d4af37] rounded-lg pl-10 pr-4 py-2.5 text-xs md:text-sm text-white focus:outline-none transition placeholder-[#685c78]"
            />
            {isCatalogSearching && (
              <RefreshCw className="absolute right-3.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[#ffd86b] animate-spin" />
            )}
          </div>

          <button
            type="button"
            onClick={() => loadIndexList(true)}
            disabled={loading}
            title="Đồng bộ lại từ Backend DB"
            className="p-2.5 rounded-lg bg-[#171320] hover:bg-[#251d33] border border-[#332842] hover:border-[#d4af37] text-[#8c7a9e] hover:text-[#ffd86b] transition active:scale-95 disabled:opacity-50"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-[#ffd86b]' : ''}`} />
          </button>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
