                  title="Play & Rate in Gameplay"
                  className="opacity-0 group-hover:opacity-100 transition-all duration-300 absolute inset-0 m-auto w-12 h-12 rounded-full bg-[#d4af37]/95 hover:bg-[#ffd86b] text-black flex items-center justify-center shadow-[0_0_20px_rgba(212,175,55,0.7)] transform scale-75 group-hover:scale-100 transition-transform duration-200 z-20 cursor-pointer"
                >
                  <Play className="w-5 h-5 fill-current ml-0.5" />
