              </button>
            </div>
            <div className="p-6 space-y-4 text-sm">
              <div>
                <span className="text-[10px] font-mono text-[#8c7a9e] uppercase block mb-1">Track Name</span>
                <p className="font-semibold text-[#f5f0e8] text-base">{inspectItem.title}</p>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="p-3 bg-[#171320] border border-[#2b2238] rounded-xl flex items-center justify-between">
                  <div>
                    <span className="text-[10px] font-mono text-[#8c7a9e] uppercase block mb-1">
                      Rank & Hazard Level
                    </span>
                    <HazardBadge
                      score={inspectItem.hazard_level}
                      rank={inspectItem.rankCategory}
                      size="lg"
                      showDetails={true}
                    />
                  </div>
                </div>
                <div className="p-3 bg-[#171320] border border-[#2b2238] rounded-xl">
                  <span className="text-[10px] font-mono text-[#8c7a9e] uppercase block">Duration</span>
                  <p className="font-mono font-semibold text-[#ffd86b] text-base mt-1">
                    {formatDuration(inspectItem.duration)}
                  </p>
                </div>
              </div>

              <div className="p-3 bg-[#171320] border border-[#2b2238] rounded-xl">
                <span className="text-[10px] font-mono text-[#8c7a9e] uppercase block">Dominant Arc</span>
                <p className="text-xs font-semibold text-[#8c7a9e] mt-0.5">
                  {inspectItem.timeblock || 'Unassigned'}
                </p>
              </div>

              <div className="relative w-full pb-[56.25%] h-0 rounded-xl overflow-hidden border border-[#2b2238]">
                <iframe
                  className="absolute top-0 left-0 w-full h-full"
                  src={`https://www.youtube-nocookie.com/embed/${inspectItem.id}?autoplay=0&rel=0`}
                  title={inspectItem.title}
                  allowFullScreen
                />
              </div>
            </div>
            <div className="p-4 border-t border-[#292033] bg-[#0d0a12] flex items-center justify-between gap-3">
              <button
                type="button"
                onClick={() => {
                  const itemToPlay = inspectItem;
                  setInspectItem(null);
                  handlePlayTrackInGameplay(itemToPlay);
                }}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-gradient-to-r from-[#d4af37] to-[#b38b19] hover:brightness-110 text-black font-cinzel font-bold text-xs rounded-xl shadow-gold-sm transition active:scale-95 cursor-pointer"
              >
                <Disc3 className="w-4 h-4 text-black animate-spin" style={{ animationDuration: '4s' }} />
                <span>Play in Gameplay & Rate</span>
                <ArrowRight className="w-4 h-4 text-black" />
              </button>
              <button
                type="button"
                onClick={() => setInspectItem(null)}
                className="px-4 py-2.5 bg-[#1a1424] hover:bg-[#251d33] border border-[#3d304f] text-[#cbd5e1] text-xs font-cinzel rounded-xl transition cursor-pointer"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

