1932	                  const pl = customPlaylists.find((p) => p.id === plId);
1933	                  return pl ? `${pl.emoji || '🎵'} ${pl.name} (${pl.channels.length} channels)` : 'Custom Playlist';
1934	                }
1935	                return selectedChannel;
1936	              })()}
1937	            </span>
1938	
1939	            {hazardCap !== 'ALL' && (
1940	              <span className="text-amber-300 font-semibold bg-amber-950/50 px-2 py-0.5 rounded border border-amber-700/50">
1941	                {getHazardCapDisplay(hazardCap)}
1942	              </span>
