1978	              className="flex items-center gap-1 bg-[#191322] px-2 py-0.5 rounded-md border border-[#3b2b4d]"
1979	              title={`${pendingLogsCount % 15}/15 logs until next automatic Tier 2 ➔ Tier 3 ➔ Tier 4 sync`}
1980	            >
