                <span className="text-[11px] font-mono text-[#8c7a9e] hidden md:inline">Exclude:</span>
                <span className={excludedChannels.length > 0 ? 'text-rose-300 font-bold' : 'text-[#a79bb7]'}>
                  {excludedChannels.length === 0
