                      >
                        Clear All
                      </button>
                    )}
                  </div>

                  {/* Tabs: Playlists vs Channels */}
                  <div className="flex border-b border-[#2b2238] bg-[#120d18] text-xs font-mono">
                    <button
                      type="button"
