                    >
                      📻 Channels ({channelList.length})
                    </button>
                  </div>

                  {excludeTab === 'playlists' ? (
                    <div className="max-h-60 overflow-y-auto p-1.5 space-y-1 scrollbar-thin">
                      {customPlaylists.length === 0 ? (
